export default async function record(
  { key, statusCode, body, clientId, workflowId, inputRate, outputRate, schema },
  ctx,
) {
  const usage = body?.usage;
  if (
    statusCode !== 200 ||
    !Number.isInteger(usage?.prompt_tokens) ||
    !Number.isInteger(usage?.completion_tokens) ||
    !Number.isInteger(usage?.total_tokens) ||
    usage.total_tokens !== usage.prompt_tokens + usage.completion_tokens
  )
    throw Error("Model response or usage unavailable; inspect pending request");
  let result;
  try {
    result = JSON.parse(body.choices[0].message.content);
  } catch {
    throw Error("Invalid model output; inspect pending request");
  }
  function validate(x, s) {
    if (s.type === "object") {
      if (!x || Array.isArray(x) || typeof x !== "object") return false;
      return Object.entries(s.properties ?? {}).every(
        ([k, v]) => x[k] === undefined || validate(x[k], v),
      );
    }
    if (s.type === "array") return Array.isArray(x) && x.every((v) => validate(v, s.items));
    return typeof x === s.type;
  }
  if (!validate(result, schema)) throw Error("Resume JSON does not match schema");
  if (
    !Number.isFinite(inputRate) ||
    inputRate < 0 ||
    !Number.isFinite(outputRate) ||
    outputRate < 0
  )
    throw Error("Configure nonnegative rates per million tokens");
  const inputCost = (usage.prompt_tokens * inputRate) / 1e6,
    outputCost = (usage.completion_tokens * outputRate) / 1e6,
    date = new Date().toISOString();
  await ctx.state.set(key, { status: "pending", phase: "sheet" });
  return {
    values: [
      [
        date,
        workflowId,
        key,
        clientId,
        "",
        usage.prompt_tokens,
        usage.completion_tokens,
        usage.total_tokens,
        inputCost,
        outputCost,
        inputCost + outputCost,
      ],
    ],
    result,
  };
}

