export default async function invoice(
  { values, clientId, recipient, acknowledge, resolution },
  ctx,
) {
  const now = new Date(),
    tomorrow = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1));
  if (tomorrow.getUTCDate() !== 1)
    return { send: false, key: "", recipient: "", subject: "", body: "" };
  if (!clientId || clientId.startsWith("YOUR_") || !recipient || recipient.startsWith("YOUR_"))
    throw Error("Configure invoice client and recipient");
  const month = now.toISOString().slice(0, 7),
    key = "cv-invoice:" + clientId + ":" + month,
    old = await ctx.state.get(key);
  if (old?.status === "done") return { send: false, key, recipient: "", subject: "", body: "" };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect unknown invoice " + key + " and reconcile before rerun");
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { send: false, key, recipient: "", subject: "", body: "" };
    }
  }
  let tokens = 0,
    cost = 0,
    count = 0;
  for (const r of values ?? []) {
    if (String(r[3]) !== clientId || !String(r[0]).startsWith(month)) continue;
    const t = Number(r[7]),
      c = Number(r[10]);
    if (!Number.isFinite(t) || !Number.isFinite(c) || t < 0 || c < 0)
      throw Error("Invalid usage row");
    tokens += t;
    cost += c;
    count++;
  }
  if (!count) return { send: false, key, recipient: "", subject: "", body: "" };
  await ctx.state.set(key, { status: "pending" });
  return {
    send: true,
    key,
    recipient,
    subject: "Invoice for " + month,
    body: `Hello,\nThis is an invoice for ${month}.\n\nTotal usage: ${tokens} tokens\nTotal token cost: $${cost.toFixed(5)}\nTax @ 20%: $${(cost * 0.2).toFixed(5)}\nTotal payable: $${(cost * 1.2).toFixed(5)}\n\nPayable within 14 days.\nThank you for your custom.`,
  };
}

